-- Condition groups for "like" codes (roadmap M6 step 4; docs/data-model.md, "Like codes").
-- Part 1, generated by drizzle-kit and corrected by hand: condition_groups gains definition,
-- sources, status (draft | published) and updated_by/at. SQLite cannot add a CHECK or a
-- timestamp default with ALTER TABLE, so the table is rebuilt. It had no rows and no routes
-- before this migration; drizzle-kit's copy selected the new columns from the old table, so
-- the INSERT below copies only the old ones.
PRAGMA foreign_keys=OFF;--> statement-breakpoint
CREATE TABLE `__new_condition_groups` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`slug` text NOT NULL,
	`name` text NOT NULL,
	`definition` text DEFAULT '' NOT NULL,
	`sources` text DEFAULT '' NOT NULL,
	`status` text DEFAULT 'draft' NOT NULL,
	`updated_by` text DEFAULT '' NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) NOT NULL,
	CONSTRAINT "condition_groups_status_check" CHECK("status" IN ('draft', 'published'))
);
--> statement-breakpoint
INSERT INTO `__new_condition_groups`("id", "slug", "name") SELECT "id", "slug", "name" FROM `condition_groups`;--> statement-breakpoint
DROP TABLE `condition_groups`;--> statement-breakpoint
ALTER TABLE `__new_condition_groups` RENAME TO `condition_groups`;--> statement-breakpoint
PRAGMA foreign_keys=ON;--> statement-breakpoint
CREATE UNIQUE INDEX `condition_groups_slug_unique` ON `condition_groups` (`slug`);--> statement-breakpoint
-- Part 2, hand-written seed: eight starter groups, all DRAFTS, for admins to check and publish
-- (Admin -> Condition groups). The groups, names, definitions and members are an AI
-- assistant's first draft (2026-11-03), on the legal review list (docs/status.md). Sources:
--   ICD-10-CM FY2027 chapter and block ranges (CMS, public domain; checked against ref_codes).
--   HCPCS Level II October 2026 (CMS, public domain): every HCPCS code and range end below
--     was checked against ref_codes; ranges follow the code set's own sections (J9000-J9999
--     chemotherapy drugs, J7500-J7599 immunosuppressive drugs, H0001-H2037 behavioral health).
--   CPT: code NUMBERS and ranges only, from the CPT section and subsection structure; never
--     AMA descriptor text (CLAUDE.md, "CPT descriptions"). Not in ref_codes, so not checked
--     here: an admin should confirm each CPT range before publishing.
--   The states' own categories (docs/sources.md): Louisiana's "Cancer", "Transplant", SMI and
--     SUD categories mix diagnosis, service and pharmacy codes, which is what a group models.
-- A member covers its codes and every code under them (conditionMemberSpan in
-- packages/shared/src/condition-groups.ts). Skips any slug that already exists.
INSERT OR IGNORE INTO `condition_groups` (`slug`, `name`, `definition`, `sources`, `status`, `updated_by`) VALUES
('cancer', 'Cancer and chemotherapy', 'Malignant cancers, and the chemotherapy and radiation therapy that treat them.', 'ICD-10-CM C00-C96 (Chapter 2, malignant neoplasms) and Z51.0-Z51.1 (encounters for radiation therapy and chemotherapy). CPT 96401-96549 (chemotherapy administration) and 77261-77799 (radiation oncology), numbers only. HCPCS J9000-J9999 (chemotherapy drugs) and Q0083-Q0085 (chemotherapy administration). Louisiana''s Cancer category spans diagnosis, service and pharmacy codes. First draft by an AI assistant; check before publishing.', 'draft', 'migration 0014'),
('kidney-failure-dialysis', 'Kidney failure and dialysis', 'Chronic kidney disease stage 5 and end-stage renal disease, and dialysis.', 'ICD-10-CM N18.5-N18.6 (CKD stage 5, ESRD), Z49 (encounter for renal dialysis) and Z99.2 (dependence on renal dialysis). CPT 90935-90999 (dialysis), numbers only. HCPCS G0257 (unscheduled dialysis for ESRD). First draft by an AI assistant; check before publishing.', 'draft', 'migration 0014'),
('organ-transplant', 'Organ transplant', 'An organ or bone marrow transplant, its complications, and the drugs that prevent rejection.', 'ICD-10-CM Z94 (transplanted organ and tissue status) and T86 (complications of transplanted organs). CPT transplant ranges, numbers only: 32850-32856 (lung), 33927-33945 (heart), 38204-38243 (bone marrow and stem cell), 44132-44137 (intestine), 47133-47147 (liver), 48550-48556 (pancreas), 50300-50380 (kidney). HCPCS J7500-J7599 (immunosuppressive drugs) without the oral steroids J7506, J7509, J7510, J7512 and J7531. Louisiana has a Transplant category. First draft by an AI assistant; check before publishing.', 'draft', 'migration 0014'),
('hiv', 'HIV', 'HIV infection, and the tests and long-acting drugs that treat it.', 'ICD-10-CM B20 (HIV disease) and Z21 (asymptomatic HIV status). CPT 87534-87539 (HIV-1 and HIV-2 nucleic acid tests), numbers only. HCPCS J0741, J1746 and J1961 (HIV treatment injections). PrEP drugs (J0738, J0739, J0752) are left out: they prevent HIV. First draft by an AI assistant; check before publishing.', 'draft', 'migration 0014'),
('serious-mental-illness', 'Serious mental illness', 'Schizophrenia and other psychotic disorders, and bipolar and major mood disorders.', 'ICD-10-CM F20-F29 (non-mood psychotic disorders) and F30-F39 (mood disorders). HCPCS H0039-H0040 (assertive community treatment), H2017-H2018 (psychosocial rehabilitation) and the long-acting injectable antipsychotics (J0401, J0402, J1631, J1942-J1944, J2358, J2426-J2428, J2680, J2794, J2798, J2799, J2801). First draft by an AI assistant; check before publishing.', 'draft', 'migration 0014'),
('substance-use-disorder', 'Substance use disorder', 'Alcohol and drug use disorders, and their treatment.', 'ICD-10-CM F10-F16 and F18-F19 (psychoactive substance use; nicotine, F17, left out). HCPCS H0001 and H0005-H0016 (alcohol and drug services), H0020 (methadone), G2067-G2080 (opioid treatment program bundles), J0571-J0578 and Q9991-Q9992 (buprenorphine) and J2315 (injectable naltrexone). First draft by an AI assistant; check before publishing.', 'draft', 'migration 0014'),
('hemophilia', 'Hemophilia and clotting factor disorders', 'Inherited bleeding disorders, and the clotting factor products that treat them.', 'ICD-10-CM D66, D67 and D68.0-D68.2 (hereditary clotting factor deficiencies, von Willebrand disease). HCPCS J7170 and J7172-J7214 (clotting factors and hemophilia drugs) without J7196-J7197 (antithrombin). First draft by an AI assistant; check before publishing.', 'draft', 'migration 0014'),
('multiple-sclerosis', 'Multiple sclerosis', 'Multiple sclerosis, and the infused or injected drugs that treat it.', 'ICD-10-CM G35 (multiple sclerosis, all its codes). HCPCS J0202, J1595, J2323, J2329, J2350, J2351 and Q5134 (MS drugs). First draft by an AI assistant; check before publishing.', 'draft', 'migration 0014');
--> statement-breakpoint
